let sellerView='overview';
let sellerMenuCategory='All';
let sellerMenuSearch='';
let sellerCart={};
let billCustomer=null;
let billSuccess=null;
let selectedSellerCustomer=null;
let editingMenuId=null;
let editingRewardId=null;
let editingPromotionId=null;
let billPreview=null;
let confirmingBill=false;
function restaurant(){return get('restaurant')}
function sellerCustomers(){return get('customer').filter(row=>row.restaurantId===restaurant().id)}
function allBills(){return get('bill').filter(row=>row.restaurantId===restaurant().id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))}
function sellerMoney(value){return formatMoney(value)}
function sellerEmpty(message,iconName='chart'){return `<div class="empty"><span data-icon="${iconName}"></span><span>${escapeHtml(message)}</span></div>`}
function sellerHydrate(root=document){qsa('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon))}
function sellerHeader(title,subtitle=''){document.querySelector('[data-page-title]').textContent=title;document.querySelector('[data-page-subtitle]').textContent=subtitle}
function todayBills(){const today=new Date().toDateString();return allBills().filter(bill=>new Date(bill.createdAt).toDateString()===today)}
function renderOverview(){const bills=todayBills(),customers=sellerCustomers(),pending=get('redemption').filter(row=>row.status==='pending'),sales=bills.reduce((sum,bill)=>sum+bill.total,0),series=[7,12,10,18,15,20].map((value,index)=>value+allBills().slice(index,index+2).reduce((sum,bill)=>sum+bill.total/100,0));sellerHeader('Overview','Today');return `<div class="seller-grid overview"><div class="stat-grid"><div class="stat-card"><span class="icon-tile">${icon('wallet')}</span><div class="stat-value">${sellerMoney(sales)}</div><div class="stat-label">Sales today</div></div><div class="stat-card"><span class="icon-tile">${icon('receipt')}</span><div class="stat-value">${bills.length}</div><div class="stat-label">Bills today</div></div><div class="stat-card"><span class="icon-tile">${icon('users')}</span><div class="stat-value">${customers.length}</div><div class="stat-label">Customers</div></div><div class="stat-card"><span class="icon-tile">${icon('gift')}</span><div class="stat-value">${pending.length}</div><div class="stat-label">Pending redemptions</div></div></div><section class="card"><div class="month-switcher"><strong>Sales</strong><span class="caption">Last 6 points</span></div>${sparkline(series)}</section><section class="card latest-bills"><div class="month-switcher"><h2 class="section-title" style="margin:0">Latest bills</h2><button class="btn btn-ghost" data-view="billing">New bill</button></div>${allBills().slice(0,5).length?`<div class="list" style="margin-top:12px">${allBills().slice(0,5).map(sellerBillRow).join('')}</div>`:sellerEmpty('No bills yet','receipt')}</section></div>`}
function sellerBillRow(bill){const customer=sellerCustomers().find(row=>row.id===bill.customerId);return `<div class="list-row"><span class="list-icon">${icon('receipt')}</span><span class="row-main"><span class="row-title">${escapeHtml(customer?.name||'Customer')}</span><span class="row-sub">${escapeHtml(bill.number)} · ${formatShortDate(bill.createdAt)}</span></span><span class="row-right"><span class="row-amount">${sellerMoney(bill.total)}</span><span class="row-meta">+${bill.pointsEarned} points</span></span></div>`}
function filteredMenu(){return get('menuItem').filter(item=>item.restaurantId===restaurant().id&&item.available&&(!sellerMenuSearch||item.name.toLowerCase().includes(sellerMenuSearch.toLowerCase()))&&(sellerMenuCategory==='All'||item.category===sellerMenuCategory))}
function cartLines(){return Object.entries(sellerCart).map(([id,qty])=>({item:get('menuItem').find(row=>row.id===id),qty})).filter(row=>row.item&&row.qty>0)}
function cartTotal(){return cartLines().reduce((sum,line)=>sum+line.item.price*line.qty,0)}
function promotionLabel(type){return ({flash_sale:'Flash sale',combo:'Combo deal',featured:'Featured item',percent_discount:'Percentage discount',fixed_discount:'Fixed discount'})[type]||'Promotion'}
function promotionDate(value){return formatDate(value,{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}
function promotionLine(promotion){return {promotionId:promotion.id,name:promotion.name,qty:1,price:Number(promotion.pricing.offerPrice)||0,items:promotion.menuItems}}
function cartPromotionLines(){return Object.entries(sellerCart).filter(([id])=>id.startsWith('promo:')).map(([key,qty])=>{const promotion=getPromotions().find(row=>row.id===key.slice(6));return promotion&&qty>0?{promotion,qty,line:promotionLine(promotion)}:null}).filter(Boolean)}
function billingLines(){return [...cartLines().map(row=>({item:row.item,qty:row.qty,price:row.item.price,name:row.item.name})),...cartPromotionLines().map(row=>({item:null,promotion:row.promotion,qty:row.qty,price:row.line.price,name:row.line.name}))]}
function billingTotal(){return billingLines().reduce((sum,line)=>sum+line.price*line.qty,0)}
function renderBilling(){const categories=['All',...new Set(get('menuItem').filter(item=>item.available).map(item=>item.category))],items=filteredMenu(),lines=billingLines(),total=billingTotal(),points=calculatePoints(total,restaurant().pointsRule),deals=eligiblePromotions(),draft=get('promotionDraft');sellerHeader('Billing','Create a paid bill');if(billSuccess)return renderBillSuccess();return `<div class="seller-grid two"><section><div class="search-bar"><span data-icon="search"></span><input class="input" id="menu-search" value="${escapeHtml(sellerMenuSearch)}" placeholder="Search menu" aria-label="Search menu"></div><div class="chips" style="margin:12px 0">${categories.map(category=>`<button class="chip ${sellerMenuCategory===category?'active':''}" data-menu-category="${escapeHtml(category)}">${escapeHtml(category)}</button>`).join('')}</div><div class="menu-grid">${items.length?items.map(item=>{const qty=sellerCart[item.id]||0;return `<div class="card menu-item"><div class="row-title">${escapeHtml(item.name)}</div><div class="menu-price">${sellerMoney(item.price)}</div><div class="menu-bottom"><span class="caption">${escapeHtml(item.category)}</span><div class="stepper"><button data-cart-minus="${item.id}" aria-label="Remove ${escapeHtml(item.name)}">−</button><strong>${qty}</strong><button data-cart-plus="${item.id}" aria-label="Add ${escapeHtml(item.name)}">${icon('plus')}</button></div></div></div>`}).join(''):sellerEmpty('No menu items','tag')}</div>${deals.length?`<div class="section-title">Active deals</div><div class="deal-list">${deals.map(p=>`<button class="deal-mini" data-cart-promotion="${p.id}"><span><strong>${escapeHtml(p.name)}</strong><small>${promotionLabel(p.type)} · ${sellerMoney(p.pricing.offerPrice)}</small></span><span class="icon-tile">${icon('plus')}</span></button>`).join('')}</div>`:''}${draft&&getPromotions().some(p=>p.id===draft.promotionId)?`<div class="card draft-callout"><div class="caption">Customer deal draft</div><p>${escapeHtml(getPromotions().find(p=>p.id===draft.promotionId).name)}</p><button class="btn btn-secondary" data-cart-promotion="${draft.promotionId}">Add draft to bill</button></div>`:''}</section><section><div class="card"><h2 class="section-title" style="margin-top:0">Customer</h2><div class="field"><label for="bill-mobile">Mobile number</label><input class="input" id="bill-mobile" inputmode="numeric" maxlength="10" value="${escapeHtml(billCustomer?.mobile||'')}" placeholder="10-digit mobile"><small class="field-error" id="bill-mobile-error"></small></div><div id="bill-customer-result">${renderBillCustomerResult()}</div><div class="month-switcher" style="margin-top:14px"><span>Points preview</span><strong class="positive">+${points}</strong></div></div><div class="card cart-card" style="margin-top:16px"><div><div class="caption">${lines.reduce((sum,line)=>sum+line.qty,0)} items</div><div class="stat-value">${sellerMoney(total)}</div></div><button class="btn btn-primary" data-preview-bill ${!lines.length?'disabled':''}>Preview bill</button></div></section></div>`}
function renderBillCustomerResult(){if(!billCustomer)return '<p class="caption">Enter a customer mobile.</p>';return billCustomer.exists?`<div class="lookup-result"><span><strong>${escapeHtml(billCustomer.name)}</strong><br><span class="caption">${billCustomer.balance} points</span></span><span class="status status-approved">Found</span></div>`:`<div class="field"><label for="new-customer-name">Customer name</label><input class="input" id="new-customer-name" value="${escapeHtml(billCustomer.name||'')}" placeholder="Customer name"><small class="field-error"></small></div>`}
function renderBillSuccess(){const bill=billSuccess.bill,customer=sellerCustomers().find(row=>row.id===bill.customerId),link=`${location.origin}${location.pathname.replace('seller/dashboard.html','customer/login.html')}?r=${encodeURIComponent(restaurant().id)}`;return `<section class="card success-card"><div class="success-icon">${icon('check',28)}</div><h2 class="page-title">Bill generated</h2><p class="page-subtitle">${escapeHtml(customer?.name||'Customer')} · ${escapeHtml(bill.number)}</p><div class="detail-list"><div class="month-switcher"><span>Total</span><strong>${sellerMoney(bill.total)}</strong></div><div class="month-switcher"><span>Points earned</span><strong class="positive">+${bill.pointsEarned}</strong></div></div><div class="message-preview"><div class="caption">Message preview</div><p>View your bill and points:</p><div class="link-box">${escapeHtml(link)}</div></div><div style="display:flex;gap:8px;justify-content:center;margin-top:16px"><button class="btn btn-secondary" data-print>${icon('printer')}Print</button><button class="btn btn-primary" data-new-bill>New bill</button></div></section>`}
function renderCustomers(){const queryValue=(document.querySelector('#customer-search')?.value||'').toLowerCase(),rows=sellerCustomers().filter(row=>!queryValue||`${row.name} ${row.mobile}`.toLowerCase().includes(queryValue));sellerHeader('Customers','Customer accounts');return `<div class="search-bar"><span data-icon="search"></span><input class="input" id="customer-search" value="${escapeHtml(queryValue)}" placeholder="Search customers" aria-label="Search customers"></div><div class="data-table" style="margin-top:12px">${rows.length?rows.map(row=>{const bills=allBills().filter(bill=>bill.customerId===row.id),spent=bills.reduce((sum,bill)=>sum+bill.total,0);return `<button class="data-table-row" data-customer="${row.id}"><span class="list-icon">${icon('user')}</span><span class="row-main"><span class="row-title">${escapeHtml(row.name)}</span><span class="row-sub">${escapeHtml(row.mobile)} · ${bills.length} bills</span></span><span class="row-right"><span class="row-amount">${sellerMoney(spent)}</span><span class="row-meta customer-points">${getBalance(row.id)} points</span></span></button>`}).join(''):sellerEmpty('No customers','users')}</div>`}
function showCustomer(customerId){selectedSellerCustomer=customerId;const customer=sellerCustomers().find(row=>row.id===customerId);if(!customer)return;const bills=allBills().filter(row=>row.customerId===customerId).slice(0,4),ledger=getCustomerLedger(customerId).slice(0,5);document.querySelector('#customer-detail').innerHTML=`<div class="profile-row"><span><strong>${escapeHtml(customer.name)}</strong><br><span class="caption">${escapeHtml(customer.mobile)}</span></span><strong>${getBalance(customerId)} points</strong></div><h3 class="section-title">Bills</h3>${bills.length?`<div class="list">${bills.map(sellerBillRow).join('')}</div>`:sellerEmpty('No bills','receipt')}<h3 class="section-title">Points</h3>${ledger.length?`<div class="list">${ledger.map(row=>`<div class="list-row"><span class="row-main"><span class="row-title">${escapeHtml(row.note||row.type)}</span><span class="row-sub">${formatShortDate(row.createdAt)}</span></span><strong class="${row.points>=0?'positive':'negative'}">${row.points>=0?'+':''}${row.points}</strong></div>`).join('')}</div>`:sellerEmpty('No points activity','chart')}<h3 class="section-title">Adjust points</h3><div class="form-grid two"><div class="field"><label for="adjust-points">Points</label><input class="input" id="adjust-points" type="number" min="1" placeholder="0"></div><div class="field"><label for="adjust-mode">Action</label><select class="select" id="adjust-mode"><option value="award">Award</option><option value="adjust">Adjust down</option></select></div></div><div class="field"><label for="adjust-reason">Reason</label><input class="input" id="adjust-reason" placeholder="Reason"></div><button class="btn btn-primary" data-save-adjust>Save</button>`;openSheet('customer-sheet')}
function renderMenu(){const items=get('menuItem').filter(row=>row.restaurantId===restaurant().id);sellerHeader('Menu','Manage items');const edit=editingMenuId?items.find(row=>row.id===editingMenuId):null;return `<section class="card"><h2 class="section-title" style="margin-top:0">${edit?'Edit item':'Add item'}</h2><div class="form-grid two"><div class="field"><label for="menu-name">Name</label><input class="input" id="menu-name" value="${escapeHtml(edit?.name||'')}" placeholder="Item name"></div><div class="field"><label for="menu-category">Category</label><input class="input" id="menu-category" value="${escapeHtml(edit?.category||'')}" placeholder="Category"></div><div class="field"><label for="menu-price">Price</label><input class="input" id="menu-price" type="number" min="0" value="${edit?.price||''}" placeholder="Price"></div><div class="field"><label for="menu-available">Availability</label><select class="select" id="menu-available"><option value="true" ${edit?.available!==false?'selected':''}>Available</option><option value="false" ${edit?.available===false?'selected':''}>Hidden</option></select></div></div><button class="btn btn-primary" data-save-menu>${edit?'Save item':'Add item'}</button>${edit?'<button class="btn btn-ghost" data-cancel-menu>Cancel</button>':''}</section><section class="card" style="margin-top:16px"><h2 class="section-title" style="margin-top:0">Items</h2><div class="data-table">${items.length?items.map(item=>`<div class="data-table-row"><span class="list-icon">${icon('tag')}</span><span class="row-main"><span class="row-title">${escapeHtml(item.name)}</span><span class="row-sub">${escapeHtml(item.category)} · ${sellerMoney(item.price)}</span></span>${item.available?'<span class="status status-paid">Available</span>':'<span class="status status-fulfilled">Hidden</span>'}<div class="inline-actions"><button class="icon-btn" data-edit-menu="${item.id}" aria-label="Edit item">${icon('edit')}</button><button class="icon-btn" data-toggle-menu="${item.id}" aria-label="Toggle item">${icon('eye')}</button><button class="icon-btn" data-delete-menu="${item.id}" aria-label="Delete item">${icon('trash')}</button></div></div>`).join(''):sellerEmpty('No menu items','tag')}</div></section>`}
function renderLoyalty(){const rule=restaurant().pointsRule,rewards=get('reward').filter(row=>row.restaurantId===restaurant().id);sellerHeader('Loyalty','Points and rewards');return `<section class="card"><h2 class="section-title" style="margin-top:0">Points rule</h2><div class="rule-options"><label class="rule-option ${rule.mode==='percent'?'selected':''}"><input type="radio" name="rule-mode" value="percent" ${rule.mode==='percent'?'checked':''}>Percent</label><label class="rule-option ${rule.mode==='perAmount'?'selected':''}"><input type="radio" name="rule-mode" value="perAmount" ${rule.mode==='perAmount'?'checked':''}>Per amount</label><label class="rule-option ${rule.mode==='flat'?'selected':''}"><input type="radio" name="rule-mode" value="flat" ${rule.mode==='flat'?'checked':''}>Flat</label></div><div class="form-grid two" style="margin-top:12px"><div class="field"><label for="rule-value">Value</label><input class="input" id="rule-value" type="number" min="0" value="${rule.mode==='percent'?rule.percent:rule.mode==='perAmount'?rule.points:rule.flatPoints}"></div><div class="field"><label for="rule-per-amount">For every rupees</label><input class="input" id="rule-per-amount" type="number" min="1" value="${rule.perAmount||100}" ${rule.mode!=='perAmount'?'disabled':''}></div></div><p class="caption" id="rule-example">${ruleExample(rule)}</p><div class="field" style="margin-top:12px"><label for="referral-reward">Referral reward points</label><input class="input" id="referral-reward" type="number" min="0" value="${restaurant().referralReward}"></div><button class="btn btn-primary" data-save-loyalty>Save settings</button></section><section class="card" style="margin-top:16px"><div class="month-switcher"><h2 class="section-title" style="margin:0">Rewards</h2><button class="btn btn-secondary" data-new-reward>Add reward</button></div><div class="data-table" style="margin-top:12px">${rewards.length?rewards.map(reward=>`<div class="data-table-row"><span class="list-icon">${icon('gift')}</span><span class="row-main"><span class="row-title">${escapeHtml(reward.name)}</span><span class="row-sub">${reward.pointsCost} points</span></span><button class="icon-btn" data-edit-reward="${reward.id}" aria-label="Edit reward">${icon('edit')}</button><button class="icon-btn" data-delete-reward="${reward.id}" aria-label="Remove reward">${icon('trash')}</button></div>`).join(''):sellerEmpty('No rewards','gift')}</div>${editingRewardId?rewardEditor(rewards.find(row=>row.id===editingRewardId)):''}</section>`}
function ruleExample(rule){return rule.mode==='percent'?`₹400 bill earns ${calculatePoints(400,{...rule,mode:'percent'})} points`:`₹400 bill earns ${calculatePoints(400,rule)} points`}
function rewardEditor(reward){return `<div class="card" style="margin-top:12px;background:var(--bg)"><div class="field"><label for="reward-name">Reward name</label><input class="input" id="reward-name" value="${escapeHtml(reward?.name||'')}" placeholder="Reward name"></div><div class="field"><label for="reward-cost">Points cost</label><input class="input" id="reward-cost" type="number" min="1" value="${reward?.pointsCost||''}" placeholder="Points"></div><button class="btn btn-primary" data-save-reward>${reward?'Save reward':'Add reward'}</button></div>`}
function renderMarketing(){const promotions=getPromotions(),active=promotions.filter(p=>promotionStatus(p)==='active').length,scheduled=promotions.filter(p=>promotionStatus(p)==='scheduled').length,expired=promotions.filter(p=>['expired','inactive','sold-out'].includes(promotionStatus(p))).length;const edit=editingPromotionId?promotions.find(p=>p.id===editingPromotionId):null;return `<div class="marketing-head"><div><h2 class="section-title" style="margin-top:0">Promotions</h2><p class="muted">Create offers customers can discover on Home.</p></div><button class="btn btn-primary" data-new-promotion>${icon('plus')}Create promotion</button></div><div class="stat-grid"><div class="stat-card"><div class="stat-value">${promotions.length}</div><div class="stat-label">Total promotions</div></div><div class="stat-card"><div class="stat-value">${active}</div><div class="stat-label">Active</div></div><div class="stat-card"><div class="stat-value">${scheduled}</div><div class="stat-label">Scheduled</div></div><div class="stat-card"><div class="stat-value">${expired}</div><div class="stat-label">Expired or inactive</div></div></div>${edit?promotionEditor(edit):''}<div class="promotion-admin-grid">${promotions.length?promotions.map(p=>{const status=promotionStatus(p);return `<article class="card promotion-admin-card"><div class="promotion-card-top"><span class="status status-${status==='active'?'paid':status==='scheduled'?'pending':status==='sold-out'?'rejected':'fulfilled'}">${status}</span><span class="caption">${escapeHtml(promotionLabel(p.type))}</span></div><h3>${escapeHtml(p.name)}</h3><p class="muted">${escapeHtml(p.description||'')}</p><p class="caption">${p.menuItems.map(item=>`${item.qty} × ${escapeHtml(item.name)}`).join(' · ')}</p><div class="month-switcher"><strong>${sellerMoney(p.pricing.offerPrice)}</strong><span class="caption">Ends ${promotionDate(p.endAt)}</span></div><div class="inline-actions"><button class="btn btn-secondary" data-edit-promotion="${p.id}">Edit</button><button class="btn btn-ghost" data-toggle-promotion="${p.id}">${p.active?'Deactivate':'Activate'}</button><button class="icon-btn" data-delete-promotion="${p.id}" aria-label="Delete ${escapeHtml(p.name)}">${icon('trash')}</button></div></article>`}).join(''):sellerEmpty('No promotions yet','tag')}</div>`}
function promotionEditor(promotion){const p=promotion||{type:'flash_sale',active:true,menuItems:[],pricing:{offerPrice:0},startAt:new Date().toISOString().slice(0,16),endAt:new Date(Date.now()+7*86400000).toISOString().slice(0,16)};const options=get('menuItem').filter(item=>item.restaurantId===restaurant().id);return `<section class="card promotion-editor"><h2 class="section-title" style="margin-top:0">${promotion?'Edit':'Create'} promotion</h2><div class="form-grid two"><div class="field"><label for="promo-name">Promotion name</label><input class="input" id="promo-name" value="${escapeHtml(p.name||'')}" placeholder="Weekend combo"></div><div class="field"><label for="promo-type">Type</label><select class="select" id="promo-type"><option value="flash_sale" ${p.type==='flash_sale'?'selected':''}>Flash sale</option><option value="combo" ${p.type==='combo'?'selected':''}>Combo deal</option><option value="featured" ${p.type==='featured'?'selected':''}>Featured item</option></select></div><div class="field"><label for="promo-items">Menu items</label><select class="select" id="promo-items" multiple size="4">${options.map(item=>`<option value="${item.id}" ${p.menuItems.some(row=>row.itemId===item.id)?'selected':''}>${escapeHtml(item.name)} · ${sellerMoney(item.price)}</option>`).join('')}</select><small class="caption">Use Ctrl or Command to select multiple items.</small></div><div class="field"><label for="promo-price">Offer price</label><input class="input" id="promo-price" type="number" min="0" value="${Number(p.pricing.offerPrice)||''}"></div><div class="field"><label for="promo-description">Description</label><textarea class="textarea" id="promo-description" placeholder="Short customer-facing description">${escapeHtml(p.description||'')}</textarea></div><div class="field"><label for="promo-limit">Quantity limit <span class="muted">(optional)</span></label><input class="input" id="promo-limit" type="number" min="1" value="${p.quantityLimit??''}" placeholder="Unlimited"></div><div class="field"><label for="promo-start">Starts</label><input class="input" id="promo-start" type="datetime-local" value="${escapeHtml(String(p.startAt).slice(0,16))}"></div><div class="field"><label for="promo-end">Ends</label><input class="input" id="promo-end" type="datetime-local" value="${escapeHtml(String(p.endAt).slice(0,16))}"></div></div><div class="preview-inline"><span class="caption">Customer preview</span><strong>${escapeHtml(p.name||'Promotion name')}</strong><span>${p.menuItems.length?escapeHtml(p.menuItems.map(row=>row.name).join(' · ')):'Select menu items'} · ${sellerMoney(p.pricing.offerPrice||0)}</span></div><div class="inline-actions"><button class="btn btn-secondary" data-cancel-promotion>Cancel</button><button class="btn btn-primary" data-save-promotion>Save promotion</button></div></section>`}
function renderSellerView(){const content=document.querySelector('#seller-content');if(sellerView==='overview')content.innerHTML=renderOverview();if(sellerView==='billing')content.innerHTML=renderBilling();if(sellerView==='customers')content.innerHTML=renderCustomers();if(sellerView==='menu')content.innerHTML=renderMenu();if(sellerView==='loyalty')content.innerHTML=renderLoyalty();if(sellerView==='marketing'){sellerHeader('Marketing','Deals and promotions');content.innerHTML=renderMarketing()}if(sellerView==='redemptions')content.innerHTML=renderRedemptions();if(sellerView==='referrals')content.innerHTML=renderReferrals();if(sellerView==='reports')content.innerHTML=renderReports();if(sellerView==='qr')content.innerHTML=renderQr();sellerHydrate(content)}
function switchSellerView(view){sellerView=view;if(view!=='billing')billSuccess=null;qsa('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===view));closeSheet('more-sheet');renderSellerView()}
function lookupBillCustomer(mobile){if(!validMobile(mobile)){billCustomer=null;return}const found=sellerCustomers().find(row=>row.mobile===mobile);billCustomer=found?{...found,exists:true,balance:getBalance(found.id)}:{mobile,name:'',exists:false}}
function validateBilling(){const lines=billingLines(),mobile=document.querySelector('#bill-mobile')?.value.trim();if(!lines.length){toast('Add an item');return null}if(!validMobile(mobile)){const error=document.querySelector('#bill-mobile-error');if(error)error.textContent='Enter a valid mobile';return null}lookupBillCustomer(mobile);let customer;if(billCustomer?.exists)customer=sellerCustomers().find(row=>row.id===billCustomer.id);else{const name=document.querySelector('#new-customer-name')?.value.trim();if(!name){document.querySelector('#bill-customer-result .field-error').textContent='Enter customer name';return null}customer={id:'pending_customer',restaurantId:restaurant().id,name,mobile,referralCode:`${name.replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase()}${Math.floor(1000+Math.random()*9000)}`,referredBy:null,joinedAt:new Date().toISOString()}}for(const row of cartPromotionLines())if(!promotionCanUse(row.promotion,row.qty)){toast(`${row.promotion.name} is no longer available`);return null}return {lines,total:billingTotal(),points:calculatePoints(billingTotal(),restaurant().pointsRule),mobile,customer}}
function renderBillPreview(){const preview=billPreview,customer=preview.customer,existing=customer.id!=='pending_customer',after=existing?getBalance(customer.id)+preview.points:preview.points;return `<div class="preview-customer"><div><strong>${escapeHtml(customer.name)}</strong><span class="caption">${escapeHtml(customer.mobile)}</span></div><span class="status ${existing?'status-approved':'status-pending'}">${existing?'Customer':'New customer'}</span></div><div class="caption" style="margin-top:16px">${promotionDate(new Date())}</div><ul class="detail-list preview-items">${preview.lines.map(line=>`<li><span>${line.qty} × ${escapeHtml(line.name)}<small>${sellerMoney(line.price)} each</small></span><strong>${sellerMoney(line.price*line.qty)}</strong></li>`).join('')}</ul><div class="detail-total"><div class="month-switcher"><span>Total payable</span><strong>${sellerMoney(preview.total)}</strong></div><div class="month-switcher"><span>Current points</span><span>${existing?getBalance(customer.id):0}</span></div><div class="month-switcher"><span>Estimated points earned</span><strong class="positive">+${preview.points}</strong></div><div class="month-switcher"><span>Balance after bill</span><strong>${after}</strong></div></div><div class="preview-actions"><button class="btn btn-secondary" data-close-sheet>Back to edit</button><button class="btn btn-primary" data-confirm-bill ${confirmingBill?'disabled':''}>Confirm &amp; Generate Bill</button></div>`}
function previewBill(){if(billSuccess||billPreview)return;const preview=validateBilling();if(!preview)return;billPreview=preview;document.querySelector('#bill-preview-detail').innerHTML=renderBillPreview();openSheet('bill-preview-sheet');sellerHydrate(document.querySelector('#bill-preview-detail'))}
function createBill(){if(confirmingBill)return;const preview=validateBilling();if(!preview)return;confirmingBill=true;let customer=preview.customer;if(customer.id==='pending_customer'){customer={...customer,id:uid('cust')};update('customer',rows=>[...rows,customer])}const items=preview.lines.map(line=>({itemId:line.item?.id||null,promotionId:line.promotion?.id||null,name:line.name,qty:line.qty,price:line.price,promotionItems:line.promotion?.menuItems||null}));const bill={id:uid('bill'),number:`MB-${1000+get('bill').length+1}`,restaurantId:restaurant().id,customerId:customer.id,items,total:preview.total,pointsEarned:preview.points,status:'paid',createdAt:new Date().toISOString()};update('bill',rows=>[...rows,bill]);addLedger(customer.id,'earned',preview.points,bill.id,'Bill points');cartPromotionLines().forEach(row=>{if(row.promotion.quantityLimit!==null)update('promotion',rows=>rows.map(p=>p.id===row.promotion.id?{...p,quantityRemaining:Math.max(0,Number(p.quantityRemaining)-row.qty),updatedAt:new Date().toISOString()}:p));update('promotionUsage',rows=>[...rows,{id:uid('promo_use'),promotionId:row.promotion.id,billId:bill.id,quantity:row.qty,createdAt:new Date().toISOString()}])});const previousPaid=get('bill').filter(row=>row.customerId===customer.id&&row.id!==bill.id&&row.status==='paid').length,ref=get('referral').find(row=>row.friendId===customer.id&&row.status==='pending');if(previousPaid===0&&ref){update('referral',rows=>rows.map(row=>row.id===ref.id?{...row,status:'rewarded',rewardedAt:new Date().toISOString()}:row));addLedger(ref.referrerId,'referral',ref.rewardPoints,ref.id,'Referral reward')}billSuccess={bill};billPreview=null;confirmingBill=false;sellerCart={};billCustomer=null;closeSheet('bill-preview-sheet');toast('Bill generated');renderSellerView()}
function saveMenu(){const name=document.querySelector('#menu-name').value.trim(),category=document.querySelector('#menu-category').value.trim(),price=Number(document.querySelector('#menu-price').value),available=document.querySelector('#menu-available').value==='true';if(!name||!category||!price){toast('Complete item details');return}if(editingMenuId)update('menuItem',rows=>rows.map(row=>row.id===editingMenuId?{...row,name,category,price,available}:row));else update('menuItem',rows=>[...rows,{id:uid('menu'),restaurantId:restaurant().id,name,category,price,available}]);editingMenuId=null;toast('Menu saved');renderSellerView()}
function saveLoyalty(){const mode=document.querySelector('input[name="rule-mode"]:checked').value,value=Number(document.querySelector('#rule-value').value)||0,perAmount=Number(document.querySelector('#rule-per-amount').value)||100,referralReward=Number(document.querySelector('#referral-reward').value)||0;update('restaurant',row=>({...row,pointsRule:{...row.pointsRule,mode,percent:mode==='percent'?value:row.pointsRule.percent,points:mode==='perAmount'?value:row.pointsRule.points,perAmount,flatPoints:mode==='flat'?value:row.pointsRule.flatPoints},referralReward}));toast('Loyalty saved');renderSellerView()}
function savePromotion(){const name=document.querySelector('#promo-name')?.value.trim(),type=document.querySelector('#promo-type')?.value,selected=[...document.querySelector('#promo-items')?.selectedOptions||[]].map(option=>option.value),offerPrice=Number(document.querySelector('#promo-price')?.value),description=document.querySelector('#promo-description')?.value.trim()||'',limitValue=document.querySelector('#promo-limit')?.value,startAt=document.querySelector('#promo-start')?.value,endAt=document.querySelector('#promo-end')?.value;if(!name||!selected.length||!Number.isFinite(offerPrice)||offerPrice<0||!startAt||!endAt||new Date(endAt)<=new Date(startAt)){toast('Complete valid promotion details');return}const items=selected.map(id=>{const item=get('menuItem').find(row=>row.id===id);return {itemId:id,qty:1,name:item.name,unitPrice:item.price}}),originalPrice=items.reduce((sum,item)=>sum+item.qty*item.unitPrice,0),limit=limitValue?Math.max(1,Number(limitValue)):null,now=new Date().toISOString();if(editingPromotionId&&editingPromotionId!=='new'){update('promotion',rows=>rows.map(p=>p.id===editingPromotionId?{...p,name,type,description,menuItems:items,pricing:{originalPrice,offerPrice},startAt:new Date(startAt).toISOString(),endAt:new Date(endAt).toISOString(),quantityLimit:limit,quantityRemaining:limit===null?null:Math.min(Number(p.quantityRemaining??limit),limit),updatedAt:now}:p))}else{update('promotion',rows=>[...rows,{id:uid('promo'),restaurantId:restaurant().id,name,type,description,menuItems:items,pricing:{originalPrice,offerPrice},startAt:new Date(startAt).toISOString(),endAt:new Date(endAt).toISOString(),active:true,quantityLimit:limit,quantityRemaining:limit,createdAt:now,updatedAt:now}])}editingPromotionId=null;toast('Promotion saved');renderSellerView()}
function saveReward(){const name=document.querySelector('#reward-name').value.trim(),pointsCost=Number(document.querySelector('#reward-cost').value);if(!name||!pointsCost){toast('Complete reward details');return}if(editingRewardId)update('reward',rows=>rows.map(row=>row.id===editingRewardId?{...row,name,pointsCost}:row));else update('reward',rows=>[...rows,{id:uid('reward'),restaurantId:restaurant().id,name,pointsCost,active:true}]);editingRewardId=null;toast('Reward saved');renderSellerView()}
function bindSellerEvents(){document.addEventListener('click',event=>{const view=event.target.closest('[data-view]');if(view){switchSellerView(view.dataset.view);return}if(event.target.closest('[data-more]')){openSheet('more-sheet');return}if(event.target.closest('[data-logout]')){logout();return}if(event.target.closest('[data-cart-plus]')){const id=event.target.closest('[data-cart-plus]').dataset.cartPlus;sellerCart[id]=(sellerCart[id]||0)+1;renderSellerView();return}if(event.target.closest('[data-cart-minus]')){const id=event.target.closest('[data-cart-minus]').dataset.cartMinus;sellerCart[id]=Math.max(0,(sellerCart[id]||0)-1);renderSellerView();return}if(event.target.closest('[data-cart-promotion]')){const id=event.target.closest('[data-cart-promotion]').dataset.cartPromotion;if(promotionCanUse(getPromotions().find(p=>p.id===id))){const key=`promo:${id}`;sellerCart[key]=(sellerCart[key]||0)+1;renderSellerView()}return}if(event.target.closest('[data-menu-category]')){sellerMenuCategory=event.target.closest('[data-menu-category]').dataset.menuCategory;renderSellerView();return}if(event.target.closest('[data-preview-bill]')){previewBill();return}if(event.target.closest('[data-confirm-bill]')){createBill();return}if(event.target.closest('[data-new-bill]')){billSuccess=null;sellerView='billing';renderSellerView();return}if(event.target.closest('[data-print]')){window.print();return}if(event.target.closest('[data-customer]')){showCustomer(event.target.closest('[data-customer]').dataset.customer);return}if(event.target.closest('[data-save-adjust]')){const points=Number(document.querySelector('#adjust-points').value),mode=document.querySelector('#adjust-mode').value,reason=document.querySelector('#adjust-reason').value.trim();if(!points||!reason){toast('Add points and reason');return}addLedger(selectedSellerCustomer,'adjust',mode==='award'?points:-points,null,reason);toast('Points updated');showCustomer(selectedSellerCustomer);return}if(event.target.closest('[data-edit-menu]')){editingMenuId=event.target.closest('[data-edit-menu]').dataset.editMenu;renderSellerView();return}if(event.target.closest('[data-cancel-menu]')){editingMenuId=null;renderSellerView();return}if(event.target.closest('[data-save-menu]')){saveMenu();return}if(event.target.closest('[data-toggle-menu]')){const id=event.target.closest('[data-toggle-menu]').dataset.toggleMenu;update('menuItem',rows=>rows.map(row=>row.id===id?{...row,available:!row.available}:row));renderSellerView();return}if(event.target.closest('[data-delete-menu]')){const id=event.target.closest('[data-delete-menu]').dataset.deleteMenu;update('menuItem',rows=>rows.filter(row=>row.id!==id));toast('Item removed');renderSellerView();return}if(event.target.closest('[data-save-loyalty]')){saveLoyalty();return}if(event.target.closest('[data-new-reward]')){editingRewardId='new';renderSellerView();return}if(event.target.closest('[data-edit-reward]')){editingRewardId=event.target.closest('[data-edit-reward]').dataset.editReward;renderSellerView();return}if(event.target.closest('[data-delete-reward]')){const id=event.target.closest('[data-delete-reward]').dataset.deleteReward;update('reward',rows=>rows.filter(row=>row.id!==id));toast('Reward removed');renderSellerView();return}if(event.target.closest('[data-save-reward]')){saveReward();return}if(event.target.closest('[data-new-promotion]')){editingPromotionId='new';renderSellerView();return}if(event.target.closest('[data-edit-promotion]')){editingPromotionId=event.target.closest('[data-edit-promotion]').dataset.editPromotion;renderSellerView();return}if(event.target.closest('[data-cancel-promotion]')){editingPromotionId=null;renderSellerView();return}if(event.target.closest('[data-toggle-promotion]')){const id=event.target.closest('[data-toggle-promotion]').dataset.togglePromotion;update('promotion',rows=>rows.map(p=>p.id===id?{...p,active:!p.active,updatedAt:new Date().toISOString()}:p));renderSellerView();return}if(event.target.closest('[data-delete-promotion]')){const id=event.target.closest('[data-delete-promotion]').dataset.deletePromotion;update('promotion',rows=>rows.filter(p=>p.id!==id));toast('Promotion removed');renderSellerView();return}if(event.target.closest('[data-save-promotion]')){savePromotion();return}});document.addEventListener('input',event=>{if(event.target.id==='menu-search'){sellerMenuSearch=event.target.value;renderSellerView()}if(event.target.id==='bill-mobile'){lookupBillCustomer(event.target.value);document.querySelector('#bill-customer-result').innerHTML=renderBillCustomerResult();const total=billingTotal();const points=document.querySelector('.positive');if(points)points.textContent=`+${calculatePoints(total,restaurant().pointsRule)}`}if(event.target.id==='customer-search'){renderSellerView()}if(event.target.id==='rule-value'||event.target.id==='rule-per-amount'){const mode=document.querySelector('input[name="rule-mode"]:checked').value;document.querySelector('#rule-example').textContent=ruleExample({mode,percent:mode==='percent'?Number(event.target.value):restaurant().pointsRule.percent,points:mode==='perAmount'?Number(event.target.value):restaurant().pointsRule.points,perAmount:Number(document.querySelector('#rule-per-amount').value)||100,flatPoints:mode==='flat'?Number(event.target.value):restaurant().pointsRule.flatPoints})}});document.addEventListener('change',event=>{if(event.target.name==='rule-mode')renderSellerView()})}
function initSellerDashboard(){if(!roleGuard('seller'))return;qsa('[data-restaurant-name]').forEach(el=>el.textContent=restaurant().name);sellerHydrate();setTimeout(()=>{renderSellerView();bindSellerEvents();setupSheets();qsa('.sheet-backdrop').forEach(backdrop=>backdrop.addEventListener('click',event=>{if(event.target===backdrop)closeSheet(backdrop)}))},180)}
function saveReward(){const name=document.querySelector('#reward-name').value.trim(),pointsCost=Number(document.querySelector('#reward-cost').value);if(!name||!pointsCost){toast('Complete reward details');return}if(editingRewardId&&editingRewardId!=='new')update('reward',rows=>rows.map(row=>row.id===editingRewardId?{...row,name,pointsCost}:row));else update('reward',rows=>[...rows,{id:uid('reward'),restaurantId:restaurant().id,name,pointsCost,active:true}]);editingRewardId=null;toast('Reward saved');renderSellerView()}
function sellerMonths(){const list=[],now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);list.push({key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,label:d.toLocaleDateString('en-IN',{month:'short'})})}return list}
function renderOverview(){const bills=todayBills(),customers=sellerCustomers(),pending=get('redemption').filter(row=>row.status==='pending'),sales=bills.reduce((sum,bill)=>sum+bill.total,0),months=sellerMonths(),series=months.map(month=>allBills().filter(bill=>{const date=new Date(bill.createdAt);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`===month.key}).reduce((sum,bill)=>sum+bill.total,0));sellerHeader('Overview','Today');return `<div class="seller-grid overview"><div class="stat-grid"><div class="stat-card"><span class="icon-tile">${icon('wallet')}</span><div class="stat-value">${sellerMoney(sales)}</div><div class="stat-label">Sales today</div></div><div class="stat-card"><span class="icon-tile">${icon('receipt')}</span><div class="stat-value">${bills.length}</div><div class="stat-label">Bills today</div></div><div class="stat-card"><span class="icon-tile">${icon('users')}</span><div class="stat-value">${customers.length}</div><div class="stat-label">Customers</div></div><div class="stat-card"><span class="icon-tile">${icon('gift')}</span><div class="stat-value">${pending.length}</div><div class="stat-label">Pending redemptions</div></div></div><section class="card"><div class="month-switcher"><strong>Sales</strong><span class="caption">Last 6 months</span></div>${sparkline(series)}</section><section class="card latest-bills"><div class="month-switcher"><h2 class="section-title" style="margin:0">Latest bills</h2><button class="btn btn-ghost" data-view="billing">New bill</button></div>${allBills().slice(0,5).length?`<div class="list" style="margin-top:12px">${allBills().slice(0,5).map(sellerBillRow).join('')}</div>`:sellerEmpty('No bills yet','receipt')}</section></div>`}
let redemptionFilter='pending';
let reportRange=30;
function renderRedemptions(){const rows=get('redemption').filter(row=>row.status===redemptionFilter).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));sellerHeader('Redemptions','Reward requests');return `<div class="segmented"><button class="segment ${redemptionFilter==='pending'?'active':''}" data-redemption-filter="pending">Pending</button><button class="segment ${redemptionFilter==='approved'?'active':''}" data-redemption-filter="approved">Approved</button><button class="segment ${redemptionFilter==='rejected'?'active':''}" data-redemption-filter="rejected">Rejected</button><button class="segment ${redemptionFilter==='fulfilled'?'active':''}" data-redemption-filter="fulfilled">Fulfilled</button></div><div class="data-table" style="margin-top:16px">${rows.length?rows.map(row=>{const customer=sellerCustomers().find(item=>item.id===row.customerId),reward=get('reward').find(item=>item.id===row.rewardId);return `<div class="data-table-row"><span class="list-icon">${icon('gift')}</span><span class="row-main"><span class="row-title">${escapeHtml(reward?.name||'Reward')}</span><span class="row-sub">${escapeHtml(customer?.name||'Customer')} · ${formatShortDate(row.createdAt)} · ${row.points} points</span></span><span class="inline-actions">${row.status==='pending'?`<button class="btn btn-primary" data-redemption-action="approve" data-redemption="${row.id}">Approve</button><button class="btn btn-danger" data-redemption-action="reject" data-redemption="${row.id}">Reject</button>`:''}${row.status==='approved'?`<button class="btn btn-primary" data-redemption-action="fulfill" data-redemption="${row.id}">Mark fulfilled</button>`:''}<span class="status status-${row.status}">${row.status}</span></span></div>`}).join(''):sellerEmpty(`No ${redemptionFilter} requests`,'gift')}</div>`}
function renderReferrals(){const referrals=get('referral'),converted=referrals.filter(row=>row.status==='rewarded'),points=converted.reduce((sum,row)=>sum+row.rewardPoints,0);sellerHeader('Referrals','Referral activity');return `<div class="stat-grid"><div class="stat-card"><span class="icon-tile">${icon('users')}</span><div class="stat-value">${referrals.length}</div><div class="stat-label">Total</div></div><div class="stat-card"><span class="icon-tile">${icon('check')}</span><div class="stat-value">${converted.length}</div><div class="stat-label">Converted</div></div><div class="stat-card"><span class="icon-tile">${icon('gift')}</span><div class="stat-value">${points}</div><div class="stat-label">Points given</div></div></div><div class="data-table" style="margin-top:16px">${referrals.length?referrals.map(row=>{const referrer=sellerCustomers().find(item=>item.id===row.referrerId),friend=sellerCustomers().find(item=>item.id===row.friendId);return `<div class="data-table-row"><span class="list-icon">${icon('users')}</span><span class="row-main"><span class="row-title">${escapeHtml(referrer?.name||'Referrer')} → ${escapeHtml(friend?.name||'Friend')}</span><span class="row-sub">${formatShortDate(row.createdAt)} · ${row.rewardPoints} points</span></span><span class="status status-${row.status}">${row.status}</span></div>`}).join(''):sellerEmpty('No referrals yet','users')}</div>`}
function reportBills(){const cutoff=Date.now()-reportRange*86400000;return allBills().filter(row=>new Date(row.createdAt).getTime()>=cutoff)}
function reportData(){const bills=reportBills(),items={},customers={},issued=bills.reduce((sum,row)=>sum+row.pointsEarned,0),redeemed=get('redemption').filter(row=>['approved','fulfilled'].includes(row.status)).reduce((sum,row)=>sum+row.points,0);bills.forEach(bill=>{const customer=sellerCustomers().find(row=>row.id===bill.customerId);customers[customer?.name||'Customer']=(customers[customer?.name||'Customer']||0)+bill.total;bill.items.forEach(item=>{items[item.name]=(items[item.name]||0)+item.qty})});const topItems=Object.entries(items).sort((a,b)=>b[1]-a[1]).slice(0,5),topCustomers=Object.entries(customers).sort((a,b)=>b[1]-a[1]).slice(0,5),newCustomers=sellerCustomers().filter(row=>new Date(row.joinedAt).getTime()>=Date.now()-reportRange*86400000).length,returning=new Set(bills.map(row=>row.customerId)).size-newCustomers,referrals=get('referral'),converted=referrals.filter(row=>row.status==='rewarded').length;return {bills,topItems,topCustomers,issued,redeemed,newCustomers,returning,referrals,converted}}
function reportRank(rows,format){const max=Math.max(...rows.map(row=>row[1]),1);return rows.length?`<div class="report-list">${rows.map(row=>`<div class="report-row"><span class="row-main"><strong>${escapeHtml(row[0])}</strong></span><div class="report-bar"><i style="width:${(row[1]/max)*100}%"></i></div><strong>${format(row[1])}</strong></div>`).join('')}</div>`:sellerEmpty('No data','chart')}
function renderReports(){const data=reportData(),months=sellerMonths(),sales=months.map(month=>data.bills.filter(bill=>{const d=new Date(bill.createdAt);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`===month.key}).reduce((sum,bill)=>sum+bill.total,0));sellerHeader('Reports',`${reportRange} day range`);return `<div class="chips"><button class="chip ${reportRange===7?'active':''}" data-report-range="7">7 days</button><button class="chip ${reportRange===30?'active':''}" data-report-range="30">30 days</button><button class="chip ${reportRange===60?'active':''}" data-report-range="60">60 days</button><button class="btn btn-secondary" data-download-csv>${icon('download')}Download CSV</button></div><div class="report-grid" style="margin-top:16px"><section class="card"><div class="month-switcher"><strong>Sales over time</strong><span class="caption">${data.bills.length} bills</span></div>${barChart(sales,months.map(month=>month.label),months.length-1)}</section><div class="seller-grid two"><section class="card"><h2 class="section-title" style="margin-top:0">Top items</h2>${reportRank(data.topItems,value=>value)}</section><section class="card"><h2 class="section-title" style="margin-top:0">Top customers</h2>${reportRank(data.topCustomers,value=>sellerMoney(value))}</section><section class="card"><h2 class="section-title" style="margin-top:0">Points</h2><div class="compare-row"><span>Issued</span><strong class="positive">${data.issued}</strong></div><div class="compare-row"><span>Redeemed</span><strong class="negative">${data.redeemed}</strong></div></section><section class="card"><h2 class="section-title" style="margin-top:0">Customers</h2><div class="compare-row"><span>New</span><strong>${Math.max(0,data.newCustomers)}</strong></div><div class="compare-row"><span>Returning</span><strong>${Math.max(0,data.returning)}</strong></div></section><section class="card"><h2 class="section-title" style="margin-top:0">Referral conversion</h2><div class="stat-value">${data.referrals.length?Math.round(data.converted/data.referrals.length*100):0}%</div><div class="stat-label">${data.converted} of ${data.referrals.length} converted</div></section></div></div>`}
function qrSvg(text){const size=29,grid=Array.from({length:size},()=>Array(size).fill(false));function finder(x,y){for(let row=0;row<7;row++)for(let col=0;col<7;col++)grid[y+row][x+col]=row===0||row===6||col===0||col===6||(row>=2&&row<=4&&col>=2&&col<=4)}finder(0,0);finder(size-7,0);finder(0,size-7);let seed=0;for(const char of text)seed=(seed*31+char.charCodeAt(0))>>>0;for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(!grid[y][x]&&!(x<8&&y<8)&&!(x>=size-8&&y<8)&&!(x<8&&y>=size-8)){seed=(seed*1664525+1013904223)>>>0;grid[y][x]=(seed>>>29)===1||((x+y)%7===0&&((seed>>>25)&1)===1)}const modules=grid.flatMap((row,y)=>row.map((on,x)=>on?`<rect x="${x}" y="${y}" width="1" height="1"/>`:'' )).join('');return `<svg class="qr-svg" viewBox="0 0 ${size} ${size}" role="img" aria-label="QR code"><rect width="${size}" height="${size}" fill="white"/>${modules}</svg>`}
function qrTarget(){return `customer/login.html?r=${encodeURIComponent(restaurant().id)}`}
function renderQr(){sellerHeader('QR code','Customer login link');const target=qrTarget();return `<section class="card qr-card"><h2 class="section-title" style="margin-top:0">${escapeHtml(restaurant().name)}</h2>${qrSvg(target)}<p class="caption">${escapeHtml(target)}</p><button class="btn btn-secondary" data-print-qr>${icon('printer')}Print table tent</button></section><section class="table-tent"><h2>${escapeHtml(restaurant().name)}</h2><p class="muted">Scan to view your points</p>${qrSvg(target)}</section>`}
function downloadBillsCsv(){const rows=[['Bill number','Customer','Mobile','Total','Points','Date'],...allBills().map(bill=>{const customer=sellerCustomers().find(row=>row.id===bill.customerId);return [bill.number,customer?.name||'',customer?.mobile||'',bill.total,bill.pointsEarned,bill.createdAt]})];const csv=rows.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download='bills.csv';link.click();URL.revokeObjectURL(url);toast('CSV downloaded')}
function handleRedemptionAction(id,action){const row=get('redemption').find(item=>item.id===id);if(!row)return;if(action==='approve')update('redemption',rows=>rows.map(item=>item.id===id?{...item,status:'approved',decidedAt:new Date().toISOString()}:item));if(action==='reject'){const reason=window.prompt('Reason')||'Rejected';update('redemption',rows=>rows.map(item=>item.id===id?{...item,status:'rejected',reason,decidedAt:new Date().toISOString()}:item));addLedger(row.customerId,'returned',row.points,row.id,'Returned: '+reason)}if(action==='fulfill')update('redemption',rows=>rows.map(item=>item.id===id?{...item,status:'fulfilled',decidedAt:item.decidedAt||new Date().toISOString()}:item));toast(action==='fulfill'?'Marked fulfilled':action==='approve'?'Approved':'Points returned');renderSellerView()}
function bindAdvancedSellerEvents(){document.addEventListener('click',event=>{if(event.target.closest('[data-redemption-filter]')){redemptionFilter=event.target.closest('[data-redemption-filter]').dataset.redemptionFilter;renderSellerView();return}if(event.target.closest('[data-redemption-action]')){const button=event.target.closest('[data-redemption-action]');handleRedemptionAction(button.dataset.redemption,button.dataset.redemptionAction);return}if(event.target.closest('[data-report-range]')){reportRange=Number(event.target.closest('[data-report-range]').dataset.reportRange);renderSellerView();return}if(event.target.closest('[data-download-csv]')){downloadBillsCsv();return}if(event.target.closest('[data-print-qr]')){window.print();return}})}
function initSellerDashboard(){if(!roleGuard('seller'))return;qsa('[data-restaurant-name]').forEach(el=>el.textContent=restaurant().name);sellerHydrate();setTimeout(()=>{renderSellerView();bindSellerEvents();bindAdvancedSellerEvents();setupSheets();qsa('.sheet-backdrop').forEach(backdrop=>backdrop.addEventListener('click',event=>{if(event.target===backdrop)closeSheet(backdrop)}))},180)}
function renderQr(){sellerHeader('QR code','Customer login link');const target=qrTarget();return `<section class="card qr-card"><h2 class="section-title" style="margin-top:0">${escapeHtml(restaurant().name)}</h2>${qrSvg(target)}<p class="caption">${escapeHtml(target)}</p><button class="btn btn-secondary" data-print-qr>${icon('printer')}Print table tent</button></section><section class="table-tent print-area"><h2>${escapeHtml(restaurant().name)}</h2><p class="muted">Scan to view your points</p>${qrSvg(target)}</section>`}
